#include <bits/stdc++.h>
using namespace std;using ll=long long;
ll H(const vector<int>&r){int n=r.size();vector<ll>d((1<<n)*n);for(int i=0;i<n;i++)d[(1<<i)*n+i]=1;for(int m=1;m<(1<<n);m++)for(int i=0;i<n;i++)if(m>>i&1){ll x=d[m*n+i];if(!x)continue;int s=r[i]&~m;while(s){int j=__builtin_ctz(s);s&=s-1;d[(m|1<<j)*n+j]+=x;}}ll h=0;for(int i=0;i<n;i++)h+=d[((1<<n)-1)*n+i];return h;}
vector<int> inflate(vector<int>r,int p,int q,int a){vector<int>lab;for(int i=0;i<(int)r.size();i++)for(int k=0;k<((i==p||i==q)?a:1);k++)lab.push_back(i);vector<int>z(lab.size());for(int i=0;i<(int)lab.size();i++)for(int j=0;j<(int)lab.size();j++)if((lab[i]==lab[j]&&i<j)||(lab[i]!=lab[j]&&(r[lab[i]]>>lab[j]&1)))z[i]|=1<<j;return z;}
vector<int> inf(vector<int>r,vector<int>s,int k){vector<int>lab;for(int i=0;i<(int)r.size();i++)for(int j=0;j<1+s[i]*k;j++)lab.push_back(i);vector<int>z(lab.size());for(int i=0;i<(int)lab.size();i++)for(int j=0;j<(int)lab.size();j++)if((lab[i]==lab[j]&&i<j)||(lab[i]!=lab[j]&&(r[lab[i]]>>lab[j]&1)))z[i]|=1<<j;return z;}
int main(){unsigned long long c;ll total=0,src=0,test=0,hits=0,survive=0;while(cin>>c){vector<int>r(9);int b=35;for(int i=0;i<9;i++)for(int j=i+1;j<9;j++){if(c>>b&1)r[i]|=1<<j;else r[j]|=1<<i;b--;}total++;ll hh=H(r);if(hh!=117&&hh!=39)continue;int G=117/hh;src++;vector<int>s(9);function<void(int,int)>visit=[&](int pos,int left){if(pos==9){int weight=accumulate(s.begin(),s.end(),0);if(!weight)return;test++;if(H(inf(r,s,1))!=837/G)return;hits++;ll h3=H(inf(r,s,2));cout<<c<<" factor "<<G<<" slopes";for(int v:s)cout<<" "<<v;cout<<" third "<<h3<<endl;if(h3==6597/G)survive++;return;}for(int t=0;t<=left;t++){s[pos]=t;visit(pos+1,left-t);}s[pos]=0;};visit(0,3);}cerr<<"TOTAL "<<total<<" sources "<<src<<" tests "<<test<<" secondhits "<<hits<<" thirdhits "<<survive<<endl;}
